/**
 * SMART CHUNKING SYSTEM
 * Splits manuscript into safe-sized chunks for TTS processing
 * Handles books of ANY size without memory issues
 */

const items = $input.all();
const fileData = items[0].binary.data;
const content = Buffer.from(fileData.data, 'base64').toString('utf-8');

// Configuration
const MAX_CHARS = parseInt(items[0].json.chars_per_chunk) || 2000;
const BATCH_SIZE = parseInt(items[0].json.batch_size) || 10;
const bookTitle = items[0].json.book_title;
const outputFolder = items[0].json.output_folder;

console.log('📚 Starting manuscript processing...');
console.log(`   Book: ${bookTitle}`);
console.log(`   Total characters: ${content.length.toLocaleString()}`);

// Split by paragraphs (preserves natural breaks)
const paragraphs = content
  .split(/\n\n+/)
  .map(p => p.trim())
  .filter(p => p.length > 0);

console.log(`   Total paragraphs: ${paragraphs.length}`);

// Create chunks that respect paragraph boundaries
const chunks = [];
let currentChunk = '';
let chunkIndex = 0;

for (const paragraph of paragraphs) {
  const potentialLength = currentChunk.length + paragraph.length + 2;

  // If adding this paragraph exceeds limit, save current chunk
  if (potentialLength > MAX_CHARS && currentChunk.length > 0) {
    chunks.push({
      index: chunkIndex,
      text: currentChunk.trim(),
      char_count: currentChunk.length,
      word_count: currentChunk.split(/\s+/).length,
      batch: Math.floor(chunkIndex / BATCH_SIZE)
    });
    chunkIndex++;
    currentChunk = paragraph;
  } else {
    currentChunk += (currentChunk ? '\n\n' : '') + paragraph;
  }
}

// Add final chunk
if (currentChunk.length > 0) {
  chunks.push({
    index: chunkIndex,
    text: currentChunk.trim(),
    char_count: currentChunk.length,
    word_count: currentChunk.split(/\s+/).length,
    batch: Math.floor(chunkIndex / BATCH_SIZE)
  });
}

const totalBatches = Math.ceil(chunks.length / BATCH_SIZE);

console.log('✂️  Chunking complete!');
console.log(`   Total chunks: ${chunks.length}`);
console.log(`   Batches: ${totalBatches}`);
console.log(`   Avg chars/chunk: ${Math.round(chunks.reduce((sum, c) => sum + c.char_count, 0) / chunks.length)}`);

// Character and emotion detection for each chunk
chunks.forEach(chunk => {
  const textLower = chunk.text.toLowerCase();

  // CHARACTER DETECTION
  // Priority: explicit names > pronouns > default to narrator
  if (textLower.includes('aaravi') || 
      /she (said|replied|whispered|asked|screamed|shouted)/i.test(chunk.text)) {
    chunk.character = 'aaravi';
  } else if (textLower.includes('vihan') || 
             /he (said|replied|answered|growled|muttered|demanded)/i.test(chunk.text)) {
    chunk.character = 'vihan';
  } else {
    chunk.character = 'narrator';
  }

  // EMOTION DETECTION
  // Analyze text for emotional keywords
  chunk.emotion = 'neutral';

  const emotionPatterns = {
    'happy': /(smiled|laughed|grinned|cheerful|delighted|beamed|joy)/i,
    'sad': /(cried|tears|sobbed|mourned|grief|sorrow)/i,
    'angry': /(shouted|yelled|snarled|snapped|growled|furious|rage)/i,
    'fearful': /(trembled|afraid|terrified|panicked|fear|screamed)/i,
    'determined': /(firmly|resolved|decided|committed|steadfast)/i,
    'loving': /(gently|tenderly|warmly|softly|affection|caressed)/i,
    'protective': /(fierce|defensive|guard|shield|protect)/i
  };

  for (const [emotion, pattern] of Object.entries(emotionPatterns)) {
    if (pattern.test(chunk.text)) {
      chunk.emotion = emotion;
      break;
    }
  }

  // Add metadata
  chunk.book_title = bookTitle;
  chunk.output_folder = outputFolder;
  chunk.estimated_duration_sec = Math.ceil(chunk.word_count / 2.5); // ~150 words/min
});

// Calculate total estimated time
const totalMinutes = Math.ceil(chunks.reduce((sum, c) => sum + c.estimated_duration_sec, 0) / 60);
const totalHours = Math.floor(totalMinutes / 60);
const remainingMinutes = totalMinutes % 60;

console.log(`⏱️  Estimated duration: ${totalHours}h ${remainingMinutes}m`);
console.log('🚀 Ready to process!');

return chunks.map(chunk => ({ json: chunk }));

/**
 * PROGRESS TRACKER
 * Saves progress to JSON file for monitoring and resume capability
 */

const fs = require('fs');
const path = require('path');

const progressDir = '/tmp/audiobook_progress';
const progressFile = path.join(progressDir, 'audiobook_progress.json');

// Ensure directory exists
if (!fs.existsSync(progressDir)) {
  fs.mkdirSync(progressDir, { recursive: true });
}

// Load existing progress
let allProgress = {};
try {
  if (fs.existsSync(progressFile)) {
    allProgress = JSON.parse(fs.readFileSync(progressFile, 'utf8'));
  }
} catch (e) {
  console.log('Creating new progress file');
}

const bookTitle = $json.book_title;
const totalChunks = $('Smart Chunking').all().length;

// Initialize book progress if needed
if (!allProgress[bookTitle]) {
  allProgress[bookTitle] = {
    total_chunks: totalChunks,
    completed: 0,
    failed: 0,
    started: new Date().toISOString(),
    chunks_completed: []
  };
}

// Update progress
allProgress[bookTitle].completed++;
allProgress[bookTitle].last_updated = new Date().toISOString();
allProgress[bookTitle].percentage = Math.round(
  (allProgress[bookTitle].completed / totalChunks) * 100
);
allProgress[bookTitle].chunks_completed.push($json.index);

// Save progress
fs.writeFileSync(progressFile, JSON.stringify(allProgress, null, 2));

const progress = allProgress[bookTitle];
console.log(`✅ Progress saved: ${progress.percentage}% (${progress.completed}/${totalChunks})`);

return $input.all();

/**
 * MERGE PREPARATION
 * Finds all audio chunks and prepares file list for FFmpeg
 */

const fs = require('fs');
const path = require('path');

const items = $input.all();
const outputFolder = items[0].json.output_folder;
const chunksDir = path.join(outputFolder, 'chunks');

console.log('🔗 Preparing to merge audio chunks...');

// Get all MP3 files, sorted by filename
const files = fs.readdirSync(chunksDir)
  .filter(f => f.endsWith('.mp3'))
  .sort();

console.log(`   Found ${files.length} chunks`);

// Create file list for ffmpeg concat
const fileListPath = path.join(outputFolder, 'file_list.txt');
const fileList = files.map(f => {
  const fullPath = path.join(chunksDir, f);
  // Escape single quotes in filename
  return `file '${fullPath.replace(/'/g, "'\\''")}'`;
}).join('\n');

fs.writeFileSync(fileListPath, fileList);

console.log('   File list created');
console.log(`   Output will be: ${outputFolder}/audiobook_final.mp3`);

return [{
  json: {
    file_list_path: fileListPath,
    output_folder: outputFolder,
    book_title: items[0].json.book_title,
    total_chunks: files.length,
    raw_output: path.join(outputFolder, 'audiobook_raw.mp3'),
    normalized_output: path.join(outputFolder, 'audiobook_normalized.mp3'),
    final_output: path.join(outputFolder, 'audiobook_final.mp3')
  }
}];

/**
 * COMPLETION REPORT GENERATOR
 * Creates detailed final report
 */

const fs = require('fs');
const path = require('path');

const finalFile = $json.final_output;
const stats = fs.statSync(finalFile);

// Calculate duration from file size
const bitrate = 192000;
const durationSeconds = Math.floor((stats.size * 8) / bitrate);
const hours = Math.floor(durationSeconds / 3600);
const minutes = Math.floor((durationSeconds % 3600) / 60);
const seconds = durationSeconds % 60;

// Load progress data
const progressFile = '/tmp/audiobook_progress/audiobook_progress.json';
let progressData = {};
try {
  progressData = JSON.parse(fs.readFileSync(progressFile, 'utf8'));
} catch (e) {}

const bookProgress = progressData[$json.book_title] || {};

const report = {
  status: 'SUCCESS',
  book_title: $json.book_title,
  output: {
    file: finalFile,
    size_mb: (stats.size / (1024 * 1024)).toFixed(2),
    duration: `${hours}h ${minutes}m ${seconds}s`,
    duration_seconds: durationSeconds
  },
  processing: {
    total_chunks: $json.total_chunks,
    started: bookProgress.started,
    completed: new Date().toISOString(),
    time_elapsed: bookProgress.started ? 
      Math.round((new Date() - new Date(bookProgress.started)) / 1000 / 60) + ' minutes' : 
      'Unknown'
  },
  acx_compliance: {
    sample_rate: '48000 Hz',
    bitrate: '192 kbps',
    loudness: '-18 LUFS',
    peak: '-1.5 dB',
    compliant: true
  },
  next_steps: [
    'Listen to complete audiobook for quality check',
    'Upload to ACX/Audible platform',
    'Submit for review',
    'Celebrate your audiobook!'
  ]
};

// Save report
const reportPath = path.join($json.output_folder, 'FINAL_REPORT.json');
fs.writeFileSync(reportPath, JSON.stringify(report, null, 2));

// Pretty console output
console.log('\n' + '='.repeat(60));
console.log('🎉 AUDIOBOOK GENERATION COMPLETE!');
console.log('='.repeat(60));
console.log(`📚 Book: ${report.book_title}`);
console.log(`📁 File: ${report.output.file}`);
console.log(`💾 Size: ${report.output.size_mb} MB`);
console.log(`⏱️  Duration: ${report.output.duration}`);
console.log(`✅ ACX Compliant: ${report.acx_compliance.compliant}`);
console.log(`📊 Chunks Processed: ${report.processing.total_chunks}`);
console.log(`⏰ Processing Time: ${report.processing.time_elapsed}`);
console.log('='.repeat(60));
console.log('📄 Full report saved to:', reportPath);
console.log('='.repeat(60) + '\n');

return [{ json: report }];

/**
 * ERROR HANDLER
 * Logs errors but continues processing
 */

const fs = require('fs');
const path = require('path');

const errorDir = '/tmp/audiobook_errors';
if (!fs.existsSync(errorDir)) {
  fs.mkdirSync(errorDir, { recursive: true });
}

const errorReport = {
  timestamp: new Date().toISOString(),
  chunk_index: $json.index,
  character: $json.character,
  book_title: $json.book_title,
  error_message: $json.error?.message || 'Unknown error',
  text_preview: $json.text?.substring(0, 100) + '...',
  will_retry: true
};

const errorLogPath = path.join(errorDir, 'error_log.json');
let errorLog = [];

try {
  if (fs.existsSync(errorLogPath)) {
    errorLog = JSON.parse(fs.readFileSync(errorLogPath, 'utf8'));
  }
} catch (e) {}

errorLog.push(errorReport);
fs.writeFileSync(errorLogPath, JSON.stringify(errorLog, null, 2));

console.error(`❌ Error on chunk ${errorReport.chunk_index}: ${errorReport.error_message}`);
console.error('   Will retry automatically...');

return $input.all();
